<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Parent/Guardian');$q=db()->prepare('SELECT s.id,u.name,s.enrollment_no FROM parent_students ps JOIN parents p ON p.id=ps.parent_id JOIN students s ON s.id=ps.student_id JOIN users u ON u.id=s.user_id WHERE p.user_id=?');$q->execute([actor_id()]);$kids=$q->fetchAll();page_top('Child Attendance');foreach($kids as $k){$a=db()->prepare('SELECT sub.code,sub.name,ROUND(100*SUM(a.status="Present")/NULLIF(COUNT(a.id),0),1) pct FROM attendance a JOIN attendance_sessions ats ON ats.id=a.session_id JOIN subjects sub ON sub.id=ats.subject_id WHERE a.student_id=? GROUP BY sub.id');$a->execute([$k['id']]);?><div class='card p-3 mb-3'><h5><?=e($k['name'].' · '.$k['enrollment_no'])?></h5><table class='table'><tr><th>Subject</th><th>Attendance</th></tr><?php foreach($a as $r):?><tr><td><?=e($r['code'].' · '.$r['name'])?></td><td><?=e($r['pct'])?>%</td></tr><?php endforeach;?></table></div><?php }page_bottom();
